/** Genuine mounted assembly followed by destructive native through-contraption decoupling. */
public final class CreateCoupledStructuralSmoke {
    @net.neoforged.fml.common.EventBusSubscriber(modid="avilixlogger") public static final class Probe {
        @net.neoforged.bus.api.SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent event){if(!Boolean.getBoolean("avilixlogger.coupledStructuralSmoke"))return;try{run(event.getServer().overworld());}catch(Throwable failure){failure.printStackTrace();System.out.println("CREATE_COUPLED_STRUCTURAL_FAILED");}finally{event.getServer().halt(false);}}
    }
    public static void run(ServerLevel world)throws Exception {
        var pos=world.getSharedSpawnPos().offset(48,47,48);world.getChunkAt(pos);var managerField=ServerLevel.class.getDeclaredField("entityManager");managerField.setAccessible(true);
        @SuppressWarnings("unchecked")var manager=(net.minecraft.world.level.entity.PersistentEntitySectionManager<net.minecraft.world.entity.Entity>)managerField.get(world);for(int i=0;i<3;i++)manager.updateChunkStatus(new net.minecraft.world.level.ChunkPos(pos.east(i*8)),net.minecraft.world.level.entity.Visibility.TRACKED);
        int tested=0;
        for(String mode:List.of("commit","cancel-world","cancel-spawn","cancel-cart-first","cancel-cart-last","world-conflict","cart-conflict","registry-conflict","survivor-conflict","apply-failure","locks","settled-registry","pending-registry","two-through","peer-no-body","effect-conflict","uuid-conflict","dual-anchor","fluid-cargo")){
            var carts=new ArrayList<Minecart>();var bodies=new ArrayList<OrientedContraptionEntity>();var controllers=new ArrayList<MinecartController>();var glues=new ArrayList<SuperGlueEntity>();CreateStructuralAudit.Scope capture=null;
            try {
                for(int i=0;i<3;i++){var base=pos.east(i*6);world.setBlock(base.below(),Blocks.STONE.defaultBlockState(),3);world.setBlock(base,AllBlocks.CART_ASSEMBLER.getDefaultState().setValue(CartAssemblerBlock.RAIL_SHAPE,RailShape.EAST_WEST),3);var cart=new Minecart(world,base.getX()+.5,base.getY(),base.getZ()+.5);check(world.addFreshEntity(cart),"base cart spawn");carts.add(cart);controllers.add(cart.getData(AllAttachmentTypes.MINECART_CONTROLLER));}
                for(int i=0;i<3;i++){var base=pos.east(i*6);var cart=carts.get(i);
                    if((mode.equals("peer-no-body")||mode.equals("dual-anchor"))&&i==1){bodies.add(null);continue;}
                    world.setBlock(base.above(),Blocks.CHEST.defaultBlockState(),3);var item=new ItemStack(Items.DIAMOND,7+i);item.set(DataComponents.CUSTOM_NAME,Component.literal("coupled cargo "+i));((ChestBlockEntity)world.getBlockEntity(base.above())).setItem(5,item);boolean dual=mode.equals("dual-anchor")&&i==0;boolean fluid=mode.equals("fluid-cargo");if(dual)for(int bridge=1;bridge<=6;bridge++)world.setBlock(base.east(bridge).above(),Blocks.STONE.defaultBlockState(),3);if(fluid){world.setBlock(base.above(2),AllBlocks.FLUID_TANK.getDefaultState(),3);var fluidStack=new net.neoforged.neoforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,2500);fluidStack.set(DataComponents.CUSTOM_NAME,Component.literal("coupled fluid components"));check(((com.simibubi.create.content.fluids.tank.FluidTankBlockEntity)world.getBlockEntity(base.above(2))).getTankInventory().fill(fluidStack,net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE)==2500,"fluid fixture setup");}var glue=new SuperGlueEntity(world,new AABB(Vec3.atLowerCornerOf(base),Vec3.atLowerCornerOf(base.offset(dual?7:1,fluid?3:2,1))));world.addFreshEntity(glue);glues.add(glue);
                    var contraption=new MountedContraption();check(contraption.assemble(world,base),"native mounted assembly");if(dual)check(contraption.connectedCart==carts.get(1),"native second anchor not found");contraption.removeBlocksFromWorld(world,BlockPos.ZERO);contraption.startMoving(world);var body=OrientedContraptionEntity.create(world,contraption,Direction.EAST);body.setPos(cart.position());check(world.addFreshEntity(body)&&body.startRiding(cart,true),"mounted representation spawn");CreateCartAudit.attach(body);bodies.add(body);
                }
                refresh(world,controllers);
                controllers.get(0).coupleWith(true,carts.get(1).getUUID(),6,true);controllers.get(1).coupleWith(false,carts.get(0).getUUID(),6,true);controllers.get(1).coupleWith(true,carts.get(2).getUUID(),6,mode.equals("two-through"));controllers.get(2).coupleWith(false,carts.get(1).getUUID(),6,mode.equals("two-through"));
                bodies.getFirst().setCouplingId(carts.get(1).getUUID());refresh(world,controllers);if(mode.equals("pending-registry"))controllers.getFirst().sendData(carts.getFirst());
                if(mode.equals("effect-conflict"))world.setBlock(pos.above(),Blocks.DIAMOND_BLOCK.defaultBlockState(),3);
                var root=controllers.get(mode.equals("two-through")?1:0);capture=CreateStructuralAudit.captureCoupled(root);
                try(var oldCapture=CreateCargoAudit.captureChanges(bodies.getFirst())){try(var normal=CreateCouplingAudit.begin()){root.decouple();normal.success();}capture.success();capture.close();check(oldCapture.rows().isEmpty(),"combined operation emitted an independent partial coupling row");}
                var before=capture.before();var after=capture.after();var plan=CreateStructuralRollbackPlan.prepare(before,after);int removedBodies=mode.equals("two-through")?3:(mode.equals("peer-no-body")||mode.equals("dual-anchor"))?1:2;
                check(plan.bodies().size()==removedBodies&&before.getList("Carts",10).size()==3&&plan.constructions().size()==((mode.equals("peer-no-body")||mode.equals("dual-anchor"))?2:3),"combined graph/body/history participants lost");check(capture.rows().size()==plan.constructions().size(),"affected participant history lost");for(var row:capture.rows())check(row.actorUuid==null&&"SYSTEM".equals(row.actorName),"automatic decoupling attributed to owner/player");
                for(String fault:List.of("bases","passenger","link","controller","body","runtime")){var bad=before.copy();switch(fault){case "bases"->bad.getList("Carts",10).remove(2);case "passenger"->bad.getList("Carts",10).getCompound(0).getList("Passengers",10).clear();case "link"->bad.getList("Bodies",10).getCompound(0).getList("Links",10).getCompound(0).putUUID("Entity",UUID.randomUUID());case "controller"->bad.getList("Carts",10).getCompound(0).getCompound("Native").putInt("Fault",1);case "body"->bad.getList("Bodies",10).remove(0);case "runtime"->bad.getList("Carts",10).getCompound(0).remove("Runtime");}reject(()->CreateStructuralRollbackPlan.prepare(bad,after),"incomplete combined scene accepted: "+fault);}
                if(mode.equals("settled-registry"))refresh(world,controllers);
                if(mode.equals("world-conflict")){var target=plan.world().stream().map(CreateStructuralRollbackPlan.World::after).filter(tag->tag.getCompound("State").getString("Name").equals("minecraft:chest")).findFirst().orElseThrow();((ChestBlockEntity)world.getBlockEntity(BlockPos.of(target.getLong("Pos")))).setItem(5,new ItemStack(Items.EMERALD,7));}
                if(mode.equals("cart-conflict"))carts.getFirst().getPersistentData().putBoolean("foreign-change",true);
                if(mode.equals("registry-conflict"))CapabilityMinecartController.loadedMinecartsByUUID.get(world).remove(carts.getFirst().getUUID());
                if(mode.equals("survivor-conflict"))bodies.getLast().setCouplingId(UUID.randomUUID());
                if(mode.equals("effect-conflict")){check(!plan.effects().isEmpty(),"replacement effect missing");var item=(net.minecraft.world.entity.item.ItemEntity)world.getEntity(plan.effects().getFirst().getUUID("Entity"));item.setItem(new ItemStack(Items.EMERALD));}
                if(mode.equals("uuid-conflict")){var copy=(OrientedContraptionEntity)net.minecraft.world.entity.EntityType.loadEntityRecursive(plan.bodies().getFirst().before().getCompound("Entity").copy(),world,e->e);check(copy!=null&&world.addFreshEntity(copy),"duplicate body fixture");bodies.add(copy);}
                if(mode.equals("apply-failure")){var tag=before.getList("Carts",10).getCompound(0);tag.getCompound("Native").putInt("RoundTripFault",1);tag.getCompound("Base").getCompound("neoforge:attachments").getCompound("create:minecart_controller").putInt("RoundTripFault",1);plan=CreateStructuralRollbackPlan.prepare(before,after);}
                var staged=plan.bodies().stream().map(body->new StagedContraptionRestore(body.before().getCompound("Entity"))).toList();var type=Class.forName("com.roften.avilixlogger.compat.create.CreateStructuralRollbackCoordinator$Job");var ctor=type.getDeclaredConstructor(net.minecraft.commands.CommandSourceStack.class,CreateStructuralRollbackPlan.class,List.class,long.class);ctor.setAccessible(true);var job=ctor.newInstance(world.getServer().createCommandSourceStack(),plan,staged,1L);var step=type.getDeclaredMethod("step",net.minecraft.server.MinecraftServer.class);step.setAccessible(true);var cancel=type.getDeclaredMethod("cancel",String.class);cancel.setAccessible(true);boolean canceled=false,rejected=false,lockChecked=false;int calls=0;boolean old=CartAuditContext.restoring(true);CartAuditContext.rollbackActive=true;
                try {
                    while(true){boolean done;try{done=(Boolean)step.invoke(job,world.getServer());}catch(InvocationTargetException failure){if(List.of("world-conflict","cart-conflict","registry-conflict","survivor-conflict","effect-conflict","uuid-conflict").contains(mode)){check(field(type,"applied").getInt(job)==0,"preflight conflict changed world");rejected=true;break;}if(mode.equals("apply-failure")){check(field(type,"cartsApplied").getInt(job)>0,"controller fault did not follow a write");cancel.invoke(job,failure.getCause().getMessage());canceled=true;continue;}throw new IllegalStateException("combined scenario "+mode,failure);}
                        if(!canceled&&(mode.equals("cancel-world")&&field(type,"applied").getInt(job)>0||mode.equals("cancel-spawn")&&field(type,"spawned").getInt(job)>0||mode.equals("cancel-cart-first")&&field(type,"cartsApplied").getInt(job)>0||mode.equals("cancel-cart-last")&&field(type,"cartsApplied").getInt(job)==3)){cancel.invoke(job,"combined cancellation");canceled=true;}
                        if(mode.equals("locks")&&!lockChecked&&field(type,"phase").getInt(job)==7){var snapshots=controllers.stream().map(CreateCartRegistry::snapshot).toList();CartAuditContext.restoring(false);try{root.decouple();controllers.getLast().prepareForCoupling(true);controllers.getFirst().tick();CapabilityMinecartController.tick(world);for(int i=0;i<3;i++)check(snapshots.get(i).equals(CreateCartRegistry.snapshot(controllers.get(i))),"reserved combined graph changed");}finally{CartAuditContext.restoring(true);}lockChecked=true;}
                        if(done)break;check(++calls<3000,"combined transaction did not finish");
                    }
                    if(List.of("world-conflict","cart-conflict","registry-conflict","survivor-conflict","effect-conflict","uuid-conflict").contains(mode))check(rejected,"conflict accepted");
                    else if(canceled){check(!field(type,"committed").getBoolean(job),"canceled transaction committed");for(var endpoint:plan.world()){var expected=endpoint.after().copy();expected.remove("Controller");check(CreateStructuralAudit.world(world,BlockPos.of(expected.getLong("Pos")),expected).equals(expected),"world compensation incomplete");}for(var body:plan.bodies())check(world.getEntity(body.before().getUUID("StorageEntity"))==null,"compensation retained recreated body");for(int i=0;i<3;i++){var actual=CreateCartRegistry.snapshot(controllers.get(i));actual.remove("Runtime");var expected=cartTag(after,carts.get(i).getUUID()).copy();expected.remove("Runtime");check(actual.equals(expected),"controller/base compensation incomplete");}}
                    else {check(field(type,"committed").getBoolean(job),"combined transaction not committed");for(var body:plan.bodies()){var entity=(OrientedContraptionEntity)world.getEntity(body.before().getUUID("StorageEntity"));check(entity!=null&&entity.getVehicle() instanceof Minecart&&CreateCartAudit.loaded(body.before().getUUID("Construction"))==entity,"body/base or logical loaded identity not restored");}for(int i=0;i<3;i++)check(CreateCartRegistry.snapshot(controllers.get(i)).equals(cartTag(before,carts.get(i).getUUID())),"full base/controller/queue checkpoint lost: "+mode+"/"+i);if(mode.equals("locks"))check(lockChecked,"combined locks not tested");}
                }finally{CartAuditContext.restoring(old);CartAuditContext.rollbackActive=false;CartAuditContext.LOCKED_ENTITIES.clear();CartRestoreLocks.clear();}tested++;
            }finally{boolean old=CartAuditContext.restoring(true);try{for(var cart:carts){for(var passenger:List.copyOf(cart.getPassengers()))if(passenger instanceof AbstractContraptionEntity entity&&!entity.isRemoved())((CartEntityAccess)entity).avilixlogger$discardForRollback();cart.discard();CapabilityMinecartController.loadedMinecartsByUUID.get(world).remove(cart.getUUID());CapabilityMinecartController.loadedMinecartsWithCoupling.get(world).remove(cart.getUUID());}for(var body:bodies)if(body!=null&&!body.isRemoved())((CartEntityAccess)body).avilixlogger$discardForRollback();for(var glue:glues)if(!glue.isRemoved())glue.discard();if(capture!=null){for(var raw:capture.after().getList("Effects",10)){var entity=world.getEntity(((CompoundTag)raw).getUUID("Entity"));if(entity!=null)entity.discard();}for(var raw:capture.before().getList("World",10))world.setBlock(BlockPos.of(((CompoundTag)raw).getLong("Pos")),Blocks.AIR.defaultBlockState(),3);}for(int bridge=1;bridge<=6;bridge++)world.setBlock(pos.east(bridge).above(),Blocks.AIR.defaultBlockState(),3);for(int i=0;i<3;i++){world.setBlock(pos.east(i*6),Blocks.AIR.defaultBlockState(),3);world.setBlock(pos.east(i*6).below(),Blocks.AIR.defaultBlockState(),3);world.setBlock(pos.east(i*6).above(),Blocks.AIR.defaultBlockState(),3);world.setBlock(pos.east(i*6).above(2),Blocks.AIR.defaultBlockState(),3);}}finally{CartAuditContext.restoring(old);CreateStructuralAudit.clear();CreateCouplingAudit.clear();}}
        }
        System.out.println("CREATE_COUPLED_STRUCTURAL_NATIVE_OK: "+tested+" scenarios; native mounted assembly, destructive through-contraption decoupling, full body/world/base/controller graph, surviving peers, original IDs and queues, commit, cancellation, partial writes, conflicts and locks");
    }
    private static CompoundTag cartTag(CompoundTag envelope,UUID id){return envelope.getList("Carts",10).stream().map(raw->(CompoundTag)raw).filter(tag->tag.getUUID("CartEntity").equals(id)).findFirst().orElseThrow();}
    private static void refresh(ServerLevel world,List<MinecartController> controllers){for(var controller:controllers)controller.tick();CapabilityMinecartController.tick(world);}
    private static Field field(Class<?> type,String name)throws Exception{var field=type.getDeclaredField(name);field.setAccessible(true);return field;}
    private static void reject(Runnable action,String message){try{action.run();}catch(IllegalStateException|IllegalArgumentException expected){return;}throw new AssertionError(message);}
    private static void check(boolean condition,String message){if(!condition)throw new AssertionError(message);}
}
